"""Ephemeral per-conversation log of LLM completion calls for the Inspector.

Stopgap for the GenAI span channel (ENG-3003 / PR #6264): until spans stream
to the Inspector, each completion call is recorded here in process memory and
shipped inside the ``skill_state`` tracker-dump payload (``llm_calls`` key).
Nothing is persisted — records never touch tracker events or tracker stores,
so retiring this module later cannot break deployments that hold old
trackers, and prompt/response content never lands in production storage. The
record vocabulary intentionally mirrors the span attributes (model, token
usage, TTFT, offered/gated/called tool names, prompt/response content) so the
frontend view carries over unchanged when the span channel lands and this
module is deleted.
"""

from __future__ import annotations

import functools
import inspect
import time
import uuid
from collections import OrderedDict, deque
from typing import (
    Any,
    Awaitable,
    Callable,
    Deque,
    Dict,
    List,
    Optional,
    TypeVar,
    Union,
    overload,
)

import structlog

from rasa.mantle.llm.client import resolve_llm_model_name, tool_schema_names
from rasa.mantle.prompts.messages import LlmMessage
from rasa.shared.providers.llm.llm_response import LLMResponse

structlogger = structlog.get_logger()

_CompletionMethod = TypeVar(
    "_CompletionMethod", bound=Callable[..., Awaitable[LLMResponse]]
)

# Parameters read from the wrapped call for the Inspector record. Resolved by
# name from kwargs, else by precomputed positional index — never via
# ``bind_partial`` on the completion hot path.
_OBSERVED_CALL_PARAMS = frozenset(
    {"self", "messages", "tools", "gated_tool_names", "model_settings"}
)

# Bounded in both dimensions: records per conversation and tracked
# conversations (LRU) — a long-running server never grows unbounded.
_MAX_RECORDS_PER_CONVERSATION = 100
_MAX_CONVERSATIONS = 200

_call_logs: "OrderedDict[str, Deque[Dict[str, Any]]]" = OrderedDict()


def _observed_param_positions(func: Callable[..., Any]) -> Dict[str, int]:
    """Map observed parameter names to positional indices for *func*."""
    return {
        name: index
        for index, name in enumerate(inspect.signature(func).parameters)
        if name in _OBSERVED_CALL_PARAMS
    }


def _observed_arg(
    name: str,
    args: tuple[Any, ...],
    kwargs: Dict[str, Any],
    positions: Dict[str, int],
) -> Any:
    """Return an observed call argument without rebinding the full signature."""
    if name in kwargs:
        return kwargs[name]
    index = positions.get(name)
    if index is not None and index < len(args):
        return args[index]
    return None


@overload
def observe_llm_call(method: _CompletionMethod) -> _CompletionMethod: ...


@overload
def observe_llm_call(
    *, purpose: Optional[str] = None
) -> Callable[[_CompletionMethod], _CompletionMethod]: ...


def observe_llm_call(
    method: Optional[_CompletionMethod] = None,
    *,
    purpose: Optional[str] = None,
) -> Union[_CompletionMethod, Callable[[_CompletionMethod], _CompletionMethod]]:
    """Record every completion made through the wrapped method in the call log.

    Keeps observability out of the engine code. Usable bare
    (``@observe_llm_call``) or parametrized
    (``@observe_llm_call(purpose="fact discovery")``).

    The wrapper is a transparent passthrough: it forwards ``*args`` / ``**kwargs``
    unchanged and only reads known parameters (``messages``, ``tools``,
    ``gated_tool_names``, ``model_settings``) for the log record when present.
    Call sites therefore do not all need the same signature. Observed args are
    resolved by name / precomputed position at decorate time so the hot path
    never runs ``inspect.signature.bind_partial``.

    The conversation id comes from the ambient turn context; when ``self``
    exposes ``_static_data.llm`` its configured model is stamped as the
    request model (otherwise the provider-reported response model suffices).
    Note: the ``finally`` below runs before a ``return`` inside ``try``
    completes, so success and failure are recorded alike.
    """

    def decorate(func: _CompletionMethod) -> _CompletionMethod:
        positions = _observed_param_positions(func)

        @functools.wraps(func)
        async def wrapper(*args: Any, **kwargs: Any) -> LLMResponse:
            from rasa.mantle.orchestration.turn_context import current_turn_context

            started = time.monotonic()
            response: Optional[LLMResponse] = None
            error_message: Optional[str] = None
            try:
                response = await func(*args, **kwargs)
                return response
            except Exception as exc:
                error_message = str(exc)
                raise
            finally:
                # Observability must never break the call: outside a bound
                # turn context (e.g. direct unit-test invocation) recording
                # is skipped rather than raised.
                try:
                    sender_id: Optional[str] = current_turn_context().sender_id
                except LookupError:
                    structlogger.debug("mantle.call_log.observe.no_turn_context")
                    sender_id = None

                self = _observed_arg("self", args, kwargs, positions)
                messages = _observed_arg("messages", args, kwargs, positions) or []
                tools = _observed_arg("tools", args, kwargs, positions)
                gated_tool_names = _observed_arg(
                    "gated_tool_names", args, kwargs, positions
                )
                model_settings = _observed_arg(
                    "model_settings", args, kwargs, positions
                )

                static_data = getattr(self, "_static_data", None)
                request_model = (
                    (resolve_llm_model_name(static_data.llm) or None)
                    if static_data is not None
                    else None
                )
                if sender_id is not None:
                    record_llm_call(
                        sender_id,
                        build_llm_call_record(
                            messages=messages,
                            tools=tools,
                            gated_tool_names=gated_tool_names,
                            model_settings=model_settings,
                            request_model=request_model,
                            latency_ms=(time.monotonic() - started) * 1000,
                            response=response,
                            error_message=error_message,
                            purpose=purpose,
                        ),
                    )

        return wrapper  # type: ignore[return-value]

    if method is not None:
        return decorate(method)
    return decorate


def record_llm_call(sender_id: str, record: Dict[str, Any]) -> None:
    """Append *record* to *sender_id*'s call log (evicting LRU conversations)."""
    log = _call_logs.get(sender_id)
    if log is None:
        log = deque(maxlen=_MAX_RECORDS_PER_CONVERSATION)
        _call_logs[sender_id] = log
    _call_logs.move_to_end(sender_id)
    log.append(record)
    while len(_call_logs) > _MAX_CONVERSATIONS:
        _call_logs.popitem(last=False)


def llm_calls_for(sender_id: str) -> List[Dict[str, Any]]:
    """Return the recorded calls for *sender_id*, oldest first."""
    log = _call_logs.get(sender_id)
    return list(log) if log else []


def clear_llm_calls(sender_id: str) -> None:
    """Drop *sender_id*'s call log (used by tests)."""
    _call_logs.pop(sender_id, None)


def _response_messages(response: LLMResponse) -> List[Dict[str, Any]]:
    """Assemble the assistant message list, mirroring the span output shape."""
    message: Dict[str, Any] = {
        "role": "assistant",
        "content": response.response_text(),
    }
    tool_calls = [
        {"id": tc.id, "name": tc.tool_name, "arguments": tc.tool_args}
        for tc in response.tool_calls or []
    ]
    if tool_calls:
        message["tool_calls"] = tool_calls
    return [message]


def build_llm_call_record(
    messages: List[LlmMessage],
    tools: Optional[List[dict]],
    gated_tool_names: Optional[List[str]],
    request_model: Optional[str],
    latency_ms: float,
    response: Optional[LLMResponse] = None,
    error_message: Optional[str] = None,
    purpose: Optional[str] = None,
    model_settings: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Build the JSON-serializable record for one completion.

    Args:
        messages: The prompt messages sent to the LLM.
        tools: Tool schemas offered to the call (OpenAI format), if any.
        gated_tool_names: Declared tools withheld by an inactive gate.
        request_model: Configured model name the call was made with.
        latency_ms: Wall-clock duration of the completion call.
        response: The completion, or ``None`` when the call raised.
        error_message: The error, for failed calls.
        purpose: Label for side-channel calls (e.g. ``"fact discovery"``);
            ``None`` for the turn's main conversation calls.
        model_settings: Allowlisted per-call overrides applied to this call.
    """
    usage = response.usage if response else None
    return {
        "id": uuid.uuid4().hex,
        "timestamp": time.time(),
        "purpose": purpose,
        "request_model": request_model,
        "response_model": response.model if response else None,
        "input_tokens": usage.prompt_tokens if usage else None,
        "output_tokens": usage.completion_tokens if usage else None,
        "latency_ms": latency_ms,
        "time_to_first_token_ms": (
            response.llm_time_to_first_token_ms if response else None
        ),
        "tool_names": tool_schema_names(tools),
        "gated_tool_names": list(gated_tool_names or []),
        "model_settings": dict(model_settings or {}),
        "response_tool_names": (
            [tc.tool_name for tc in response.tool_calls or []] if response else []
        ),
        "prompt_messages": [dict(message) for message in messages],
        "response_messages": _response_messages(response) if response else None,
        "is_error": response is None,
        "error_message": error_message,
    }
